'use strict';

/**
 * model.cjs — resolves the model behind Bugbot.
 *
 * Set BUGBOT_MODEL to a path of a module exporting either:
 *   module.exports = async function call(system, prompt) { return 'text'; }
 * or
 *   module.exports = { call: async (system, prompt) => 'text' };
 *
 * With no adapter configured, a built-in deterministic echo model runs the
 * whole pipeline with no API key: the finder returns a clean review ([]),
 * the refuter kills anything it is shown. Safe-by-default for CI.
 */

const path = require('path');

function builtinEcho() {
  return {
    name: 'echo',
    async call(system, prompt) {
      if (/BUGBOT-REFUTER/i.test(system)) {
        return '{"verdict":"kill","reason":"echo model refutes by default — wire BUGBOT_MODEL for real review"}';
      }
      return '[]';
    },
  };
}

function resolveModel() {
  const spec = process.env.BUGBOT_MODEL;
  if (!spec) return builtinEcho();
  try {
    const mod = require(path.resolve(process.cwd(), spec));
    const fn = typeof mod === 'function' ? mod : mod && typeof mod.call === 'function' ? mod.call.bind(mod) : null;
    if (!fn) throw new Error('adapter must export async call(system, prompt) or be a function');
    return { name: mod.name || spec, call: fn };
  } catch (e) {
    console.error('bugbot: could not load BUGBOT_MODEL adapter (' + String((e && e.message) || e) + ') — using built-in echo model');
    return builtinEcho();
  }
}

module.exports = { resolveModel, builtinEcho };

'use strict';

/**
 * model-adapter.cjs — copyable template for wiring a REAL model into Bugbot.
 *
 *   BUGBOT_MODEL=./examples/model-adapter.cjs git diff | node lib/bugbot.cjs
 *
 * Contract: export an async function call(system, prompt) that returns the
 * model's raw text reply. That's the whole integration surface. Point the
 * fetch below at any OpenAI-compatible endpoint (or swap in any SDK).
 */

const ENDPOINT = process.env.MODEL_ENDPOINT || 'http://localhost:11434/v1/chat/completions';
const MODEL = process.env.MODEL_NAME || 'your-model-name';
const API_KEY = process.env.MODEL_API_KEY || '';

module.exports = async function call(system, prompt) {
  const res = await fetch(ENDPOINT, {
    method: 'POST',
    headers: Object.assign(
      { 'content-type': 'application/json' },
      API_KEY ? { authorization: 'Bearer ' + API_KEY } : {}
    ),
    body: JSON.stringify({
      model: MODEL,
      max_tokens: 16384,
      temperature: 0,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: prompt },
      ],
    }),
    signal: AbortSignal.timeout(120000),
  });
  if (!res.ok) throw new Error('model endpoint HTTP ' + res.status);
  const json = await res.json();
  return (json.choices && json.choices[0] && json.choices[0].message && json.choices[0].message.content) || '';
};

'use strict';

/**
 * _demo-model.cjs — scripted model for examples/demo.cjs. Deterministic, offline.
 * Plays the finder (returns two candidates) and the refuter (kills one, confirms one).
 */

const FINDER_REPLY = JSON.stringify([
  {
    file: 'src/user-service.js',
    line: 12,
    severity: 'critical',
    summary: 'Null dereference: the removed !user guard means user.id throws when the query returns no rows',
    failure_scenario: 'Given an id with no matching row, res.rows[0] is undefined and the return object construction throws TypeError instead of NotFoundError',
    suggested_fix: "Restore the guard: if (!user) throw new NotFoundError('user ' + id) before building the return object",
  },
  {
    file: 'src/user-service.js',
    line: 21,
    severity: 'major',
    summary: 'Possible null dereference: label.toUpperCase() when user has neither name nor email',
    failure_scenario: 'Given a user object with null name and null email, label is null and toUpperCase() throws',
    suggested_fix: "Fallback: const label = user.name || user.email || ''",
  },
]);

const CONFIRM = JSON.stringify({
  verdict: 'confirm',
  reason: 'The diff removed the only !user guard; no surrounding check prevents res.rows[0] being undefined, so user.id is a reachable TypeError.',
});

const KILL = JSON.stringify({
  verdict: 'kill',
  reason: 'The same diff adds `if (!user) return "(missing)"` at the top of formatUser, and label falls back name→email; a user with neither is not shown reachable from this change.',
});

module.exports = async function call(system, prompt) {
  if (/BUGBOT-REFUTER/i.test(system)) {
    return /removed !user guard/.test(prompt) ? CONFIRM : KILL;
  }
  return FINDER_REPLY;
};
